const BENCH_ACCESS = {"117f7:HearthFires.esm":{"anyone":false,"halves":{"confectioner":"novice","hearthcook":"novice"},"name":"BYOHCraftingOven"},"1547f:Thornswood-Content.esp":{"anyone":false,"halves":{"charburner":"novice"},"name":"ThornswoodCraftingCharcoalKiln"},"17738:Dragonborn.esm":{"anyone":false,"halves":{"bladebinder":"novice"},"name":"DLC2StaffEnchanter"},"18cb1:Dragonborn.esm":{"anyone":true,"halves":{},"name":"testPhilCraftingBreakItDowner"},"3015:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingCarpenter"},"305c:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingDrafting"},"5756:Dawnguard.esm":{"anyone":true,"halves":{"bladebinder":"master","platewright":"master"},"name":"DLC1LD_CraftingForgeAetherium"},"59d8:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart006Chest01"},"59e1:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart043ShelfTallDisplayCase01"},"59e7:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart024WeaponPlaque01"},"5a0c:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart065MountedHeadSabreCat02"},"6ce000:Update.esm":{"anyone":true,"halves":{"haberdasher":"novice","liverywright":"novice"},"name":"MCE_CraftingLoom"},"7866a:Skyrim.esm":{"anyone":true,"halves":{"haberdasher":"novice","liverywright":"novice","platewright":"novice"},"name":"CraftingTanningRack"},"88105:Skyrim.esm":{"anyone":true,"halves":{"edgewright":"novice","haberdasher":"novice","liverywright":"master","platewright":"novice","woodwright":"novice"},"name":"CraftingSmithingForge"},"88108:Skyrim.esm":{"anyone":false,"halves":{"edgewright":"novice","woodwright":"novice"},"name":"CraftingSmithingSharpeningWheel"},"910:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart199WallSconceExteriorx2"},"9b8:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart201TableSquare02"},"9c6de:Skyrim.esm":{"anyone":false,"halves":{"hearthcook":"novice"},"name":"isGrainMill"},"a0c:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart202TableNightx2_02"},"a31b:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingTrophyBase1"},"a31c:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingTrophyBase2"},"a5cb3:Skyrim.esm":{"anyone":true,"halves":{"hearthcook":"novice"},"name":"CraftingCookpot"},"a5cce:Skyrim.esm":{"anyone":true,"halves":{},"name":"CraftingSmelter"},"adb78:Skyrim.esm":{"anyone":true,"halves":{"platewright":"novice"},"name":"CraftingSmithingArmorTable"},"alchemy":{"anyone":false,"halves":{"blightbrewer":"novice","physicker":"novice"},"name":"the alchemy lab"},"b28:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart205TableNight01"},"b59:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart206ShrineDibella"},"b68f:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart124WallShelf01"},"b696:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart126ChairExterior01"},"d16c:HearthFires.esm":{"anyone":true,"halves":{},"name":"BYOHBuildingInteriorPart158ChestExterior01"},"enchanting":{"anyone":false,"halves":{"bladebinder":"novice","wardweaver":"novice"},"name":"the arcane enchanter"},"f46ce:Skyrim.esm":{"anyone":false,"halves":{"edgewright":"advanced","platewright":"advanced","woodwright":"advanced"},"name":"CraftingSmithingSkyforge"},"f806:Dawnguard.esm":{"anyone":false,"halves":{"woodwright":"advanced"},"name":"DLC1CraftingDawnguard"}};
