    rankUp: rankUp, pickThirdSchool: pickThirdSchool, spendPoint: spendPoint,
    perks: perks, canWork: canWork, canDo: canDo,
    halvesOf: halvesOf, sisterOf: sisterOf, classFor: classFor,
